title: ${yamlQuote(test.title.replace(/\.$/, ""))}
description: ${yamlQuote(test.description)}
slug: docs/tests/${test.id}
editUrl: ${yamlQuote(`https://github.com/maester365/maester/edit/main/${test.sourceMarkdownFile || test.sourceFunctionFile}`)}
tableOfContents: false
head:
  - tag: title
    content: ${yamlQuote(`${shorten(test.title.replace(/\.$/, ""), 50)} (${test.id}) | Maester`)}
maester:
  kind: test
  id: ${yamlQuote(test.id)}
  suite: ${yamlQuote(test.suite)}
  severity: ${yamlQuote(test.severity)}
  product: ${yamlQuote(test.product)}
  feature: ${yamlQuote(test.feature)}
  previewOnly: ${!releasedTests.has(test.id)}
  previewCheck: ${test.lifecycle === "Preview"}
---

${body.join("\n")}`;
}

